import {generateTabulatorTableFromCSV} from "8bb63a6cde9addff"
generateTabulatorTableFromCSV(
  "#my-table",                          // CSS selector for the table container
     "includes/GCSFIdata.csv",      // &lt;-- plug in your CSV URL or file path here

  {
    displayedColumns: [
      "Title", 
      "Venue", 
      "Published in ", 
      "Year", 
      "Author Name (first last as published)",
      "Nationality or Associated Country", 
      "Plot Description", 
      "Thematic Keywords",  
      "Scene setting",
      "Characters",
      "Issue URL",
             // columns to show (in order)

    ],
columnWidths: {
    "Plot Description": "30px",
    // Add others if you want
  },
    numericColumns: [
      "Year"],       // columns to treat as numbers (enables range filters)

    categoryColumns: [""],      // columns to treat as categories (enables dropdown filters)

    sortColumns: ["Venue"],          // default sort column(s)
    sortOrders: ["asc"],                 // "asc" or "desc" for each sort column

  }
);
html`&lt;div id='button-container2'&gt;
  &lt;button id="download-raw"&gt;&lt;i class="fas fa-download"&gt;&lt;/i&gt;&lt;/i&gt; Download Full Data&lt;/button&gt;
  &lt;button id="copy-url"&gt;&lt;i class="fas fa-copy"&gt;&lt;/i&gt; Copy Full Data URL&lt;/button&gt;
&lt;/div&gt;`
